using System;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using EarthUnscripted.NewbridgePrototype;
namespace EarthUnscripted.Editor {
[InitializeOnLoad] public static class SignReadabilityVerification {
 const string Key="EUSignRender";static int frames;static RenderTexture rt;static Camera camera;static GameObject root;
 static SignReadabilityVerification(){if(!SessionState.GetBool(Key,false))return;GameSession.SuppressAutomaticLaunch=true;EditorApplication.update+=Tick;}
 public static void Run(){GameSession.SuppressAutomaticLaunch=true;UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene);SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void Tick(){try{if(!EditorApplication.isPlaying)return;if(!camera){GameSession.SuppressAutomaticLaunch=true;root=new GameObject("Signs");int i=0;foreach(string value in new[]{"20","30","50","70"}){var sign=StandardTrafficSigns.Place(root.transform,"speed",value,"GB");sign.transform.position=new Vector3(i++*.95f,0,0);}var go=new GameObject("Camera");camera=go.AddComponent<Camera>();camera.transform.position=new Vector3(1.425f,0,4);camera.transform.rotation=Quaternion.Euler(0,180,0);camera.orthographic=true;camera.orthographicSize=.53f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.3f,.4f,.5f);rt=new RenderTexture(1200,300,24);camera.targetTexture=rt;var volume=new GameObject("Exposure").AddComponent<Volume>();volume.isGlobal=true;volume.sharedProfile=ScriptableObject.CreateInstance<VolumeProfile>();var exposure=volume.sharedProfile.Add<UnityEngine.Rendering.HighDefinition.Exposure>();exposure.mode.Override(UnityEngine.Rendering.HighDefinition.ExposureMode.Fixed);exposure.fixedExposure.Override(0);return;}if(++frames==20){var font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");for(int size=12;size<100;size+=3)font.RequestCharactersInTexture("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",size,FontStyle.Normal);}if(frames<40)return;RenderTexture.active=rt;var image=new Texture2D(1200,300,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,300),0,0);image.Apply();Directory.CreateDirectory("Builds/Verification/Signs");File.WriteAllBytes("Builds/Verification/Signs/"+GameGraphics.Name+".png",image.EncodeToPNG());Debug.Log("SIGN RENDER "+GameGraphics.Name);SessionState.SetBool(Key,false);EditorApplication.update-=Tick;EditorApplication.Exit(0);}catch(Exception e){SessionState.SetBool(Key,false);Debug.LogException(e);EditorApplication.Exit(1);}}
}}
